function csvCell(v){v=v==null?"":Array.isArray(v)?v.join("|"):String(v);return/[",\n;]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}
function exportCsv(){q(sb.from("content").select("*,content_genres(genre_slug,position)").is("deleted_at",null).order("created_at")).then(function(rows){
  var out=[COLS.join(",")].concat(rows.map(function(r){r.genres=(r.content_genres||[]).sort(function(a,b){return a.position-b.position}).map(function(g){return g.genre_slug});return COLS.map(function(c){return csvCell(r[c])}).join(",")}));
  var a=document.createElement("a");a.href=URL.createObjectURL(new Blob(["﻿"+out.join("\n")],{type:"text/csv;charset=utf-8"}));a.download="kinoua-catalog-"+new Date().toISOString().slice(0,10)+".csv";document.body.appendChild(a);a.click();a.remove();toast("Експортовано: "+rows.length)}).catch(fail)}
function parseCsv(t){var rows=[],row=[],f="",i=0,qd=false;t=t.replace(/^﻿/,"");for(;i<t.length;i++){var c=t[i];if(qd){if(c==='"'){if(t[i+1]==='"'){f+='"';i++}else qd=false}else f+=c}else if(c==='"')qd=true;else if(c===","){row.push(f);f=""}else if(c==="\n"||c==="\r"){if(c==="\r"&&t[i+1]==="\n")i++;row.push(f);rows.push(row);row=[];f=""}else f+=c}if(f||row.length){row.push(f);rows.push(row)}return rows.filter(function(r){return r.some(function(x){return x.trim()})})}
function importCsv(file,m){file.text().then(function(txt){var rs=parseCsv(txt);if(rs.length<2)throw new Error("Файл порожній.");var h=rs[0].map(function(x){return x.trim()});["slug","ty","title_orig"].forEach(function(k){if(h.indexOf(k)<0)throw new Error("Немає обов’язкової колонки «"+k+"».")});
  var items=rs.slice(1).map(function(r,n){var o={_line:n+2};h.forEach(function(k,i){o[k]=(r[i]||"").trim()});return o});
  return Promise.all([q(sb.from("content").select("slug,title_orig,year")),q(sb.from("genres").select("slug"))]).then(function(r){var slugs={},tt={},gs={};r[0].forEach(function(c){slugs[c.slug]=1;tt[(c.title_orig||"").toLowerCase()+"|"+c.year]=c.slug});r[1].forEach(function(g){gs[g.slug]=1});
    var ok=[],skip=[],dupw=[];items.forEach(function(o){var err=[];if(!/^[a-z0-9][a-z0-9-]{1,99}$/.test(o.slug))err.push("slug");if(["films","cartoons","series"].indexOf(o.ty)<0)err.push("ty");if(!o.title_orig)err.push("title_orig");if(o.year&&!/^\d{4}$/.test(o.year))err.push("year");
      if(slugs[o.slug])err.push("slug уже є");if(err.length){skip.push("рядок "+o._line+": "+err.join(", "));return}var k=o.title_orig.toLowerCase()+"|"+(o.year||"");if(tt[k])dupw.push(o.title_orig+" ("+o.year+") — схоже на «"+tt[k]+"»");slugs[o.slug]=1;ok.push(o)});
    var d=document.createElement("dialog");d.innerHTML='<h2>Імпорт CSV</h2><p>Буде створено <b>'+ok.length+'</b> чернеток (не публікуються автоматично).</p>'+(skip.length?'<p style="color:var(--bad)">Пропущено '+skip.length+':</p><ul class="note">'+skip.slice(0,12).map(function(x){return'<li>'+esc(x)+'</li>'}).join("")+'</ul>':'')+(dupw.length?'<p style="color:var(--warn)">Можливі дублікати:</p><ul class="note">'+dupw.slice(0,12).map(function(x){return'<li>'+esc(x)+'</li>'}).join("")+'</ul>':'')+'<div class="dacts"><button type="button" class="btn sec" value="0">Скасувати</button><button type="button" class="btn" value="1"'+(ok.length?'':' disabled')+'>Створити чернетки</button></div>';
    document.body.appendChild(d);var go1=function(y){X.shut(d);if(!y)return;
      var arr=function(v){return v?v.split("|").map(function(x){return x.trim()}).filter(Boolean):[]},num=function(v){return v===""||v==null?null:+v};
      var rows=ok.map(function(o){return{slug:o.slug,ty:o.ty,title_orig:o.title_orig,title_uk:o.title_uk||null,title_ru:o.title_ru||null,year:num(o.year),premiere_date:o.premiere_date||null,runtime_min:num(o.runtime_min),release_status:REL.some(function(x){return x[0]===o.release_status})?o.release_status:"released",
        orig_lang:/^[a-z]{2,3}$/.test(o.orig_lang||"")?o.orig_lang:null,countries:arr(o.countries),tags:arr(o.tags),imdb_id:/^tt\d{7,9}$/.test(o.imdb_id||"")?o.imdb_id:null,rating_imdb:num(o.rating_imdb),rating_imdb_votes:num(o.rating_imdb_votes),trailer_yt:/^[\w-]{11}$/.test(o.trailer_yt||"")?o.trailer_yt:null,poster:o.poster||null,pub_status:"draft"}});
      q(sb.from("content").insert(rows).select("id,slug")).then(function(ins){var map={};ins.forEach(function(c){map[c.slug]=c.id});var cg=[];ok.forEach(function(o){arr(o.genres).forEach(function(g,i){if(gs[g]&&map[o.slug])cg.push({content_id:map[o.slug],genre_slug:g,position:i})})});
        return(cg.length?q(sb.from("content_genres").insert(cg)):Promise.resolve()).then(function(){toast("Імпортовано чернеток: "+ins.length);LQ.st="draft";LQ.trash=false;list(m)})}).catch(fail)};$$("button",d).forEach(function(b){b.onclick=function(){go1(b.value==="1")}});d.addEventListener("cancel",function(e){e.preventDefault();go1(false)});d.showModal()})}).catch(function(e){toast(String(e.message||e),true)})}

