 +'<td><input class="in" data-s="ref" data-i="'+i+'" value="'+esc(s.ref||"")+'" style="min-width:220px" placeholder="https://… або ID"></td><td><input class="in" data-s="label" data-i="'+i+'" value="'+esc(s.label||"")+'" maxlength="80" style="min-width:120px"></td><td><input class="in" data-s="lang" data-i="'+i+'" value="'+esc(s.lang||"")+'" maxlength="3" style="width:70px" placeholder="uk"></td>'
